## C++ 

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
	int n;
	vector<long long> bit;
	Fenwick(int n=0): n(n), bit(n+1, 0) {}
	void add(int idx, long long delta) {
		for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
	}
	long long sumPrefix(int idx) const {
		long long res = 0;
		for (; idx > 0; idx -= idx & -idx) res += bit[idx];
		return res;
	}
	long long sumRange(int l, int r) const {
		return sumPrefix(r) - sumPrefix(l - 1);
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, q;
	if (!(cin >> n >> q)) return 0;
	vector<long long> a(n + 1);
	for (int i = 1; i <= n; ++i) cin >> a[i];

	// 一个树状数组维护和，另一个维护平方和
	Fenwick bitSum(n), bitSq(n);
	for (int i = 1; i <= n; ++i) {
		bitSum.add(i, a[i]);
		bitSq.add(i, a[i] * a[i]);
	}

	cout.setf(std::ios::fixed);
	cout << setprecision(6);

	while (q--) {
		int t; cin >> t;
		if (t == 1) {
			int i; long long x; cin >> i >> x;
			// 单点修改：更新和与平方和
			long long delta = x - a[i];
			long long deltaSq = x * x - a[i] * a[i];
			bitSum.add(i, delta);
			bitSq.add(i, deltaSq);
			a[i] = x;
		} else {
			int l, r; cin >> l >> r;
			long long S = bitSum.sumRange(l, r);
			long long Q = bitSq.sumRange(l, r);
			long double m = (long double)(r - l + 1);
			long double mean = S / m;
			long double var = Q / m - mean * mean;
			if (var < 0 && var > -1e-12) var = 0; // 数值误差修正
			cout << (double)var << '\n';
		}
	}
	return 0;
}
```

